import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0053 — Navigazione dei disegni: zoom sulla selezione e mini-mappa (M18)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0053-navigazione-dei-disegni.md","filePath":"adr/0053-navigazione-dei-disegni.md"}'),t={name:"adr/0053-navigazione-dei-disegni.md"};function d(l,e,s,r,c,u){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0053-—-navigazione-dei-disegni-zoom-sulla-selezione-e-mini-mappa-m18" tabindex="-1">ADR-0053 — Navigazione dei disegni: zoom sulla selezione e mini-mappa (M18) <a class="header-anchor" href="#adr-0053-—-navigazione-dei-disegni-zoom-sulla-selezione-e-mini-mappa-m18" aria-label="Permalink to &quot;ADR-0053 — Navigazione dei disegni: zoom sulla selezione e mini-mappa (M18)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata il 2026-11-15 (decisione dell&#39;owner); implementata in M18 e rilasciata con la 1.6.0</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.6 (2026-11-15): §2.2.1, §2.7.2 (punto 10) e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.7.2 (comportamento UI dei disegni), V-04 (Excalidraw integrato nativamente), V-02/D-01 (architettura chiusa: niente richieste di rete né CSS dell&#39;autore); ADR-0010 (disegni), ADR-0024 (azioni sulla scena), ADR-0028 (fork di Excalidraw), ADR-0037 e ADR-0045 (registro delle funzioni e parità)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no, è un&#39;aggiunta che lo spec non prevede: §2.7.2 va integrato con un punto «Navigazione» (zoom sulla selezione e mini-mappa). Nessun testo esistente è contraddetto. Se si vuole, la matrice delle funzioni (§2.2.1, riga «Excalidraw nativo») può citare la nuova voce di parità <code>drawing.navigation</code></td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: <code>viewport.test.ts</code>, <code>uiPrefs.test.ts</code>, <code>minimap/geometry.test.ts</code>, <code>minimap/model.test.ts</code>, e2e <code>drawing-navigation.spec.ts</code> sul mock dei binding) · workbench web (stessa UI; prova: lo stesso <code>drawing-navigation.spec.ts</code> sul core WASM nel browser) · console: non applicabile · cloud: non applicabile. Registro: voce <code>drawing.navigation</code> di <code>shared/parity/features.yaml</code></td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il disegno si modifica con il fork di Excalidraw <code>@zsviczian/excalidraw@0.18.145</code> (ADR-0028). Prima di M18 la navigazione di un disegno grande aveva due lacune:</p><ul><li>lo zoom sulla selezione esisteva solo come azione di scena (<code>drawing:zoom-to-fit-selected</code>), senza un pulsante, spento in sola lettura e insieme al flag <code>drawing_actions</code>, e il fit non teneva conto della barra inferiore dell&#39;editor;</li><li>non c&#39;era alcuna vista d&#39;insieme: su una lavagna grande si perdeva l&#39;orientamento.</li></ul><p>La richiesta era di avere i due strumenti accanto al controllo di zoom di Excalidraw, in basso a sinistra. Il piano prevedeva di passarli come figli dello slot <code>&lt;Footer&gt;</code> di Excalidraw. Provando, lo slot non è reso nel layout «tray», cioè quello di un disegno modificabile: esiste solo nel layout completo, non in quello che l&#39;utente usa per scrivere. Perciò la soluzione prevista non funziona proprio dove serve.</p><p>I vincoli sono quelli di sempre: nessuna richiesta di rete, solo token di colore, nessuna modifica del fork, parità per costruzione tra desktop e workbench web (ADR-0045).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Un gruppo di due pulsanti flottante, ancorato all&#39;isola dello zoom</strong> (<code>packages/workbench/src/drawing/NavigationTools.tsx</code>, stile <code>.drawing-nav-tools</code> in <code>style.css</code>): <em>Zoom sulla selezione</em> e <em>Mini-mappa</em> (a interruttore, con <code>aria-pressed</code>). Il gruppo è un elemento nostro dentro il contenitore dell&#39;editor, in <code>position: absolute</code>: nulla viene aggiunto al DOM di Excalidraw. Si posiziona misurando l&#39;isola dello zoom (<code>.excalidraw .zoom-actions</code>, poi il suo <code>.Island</code> o, nel layout completo, <code>.layer-ui__wrapper__footer-left</code>) con <code>getBoundingClientRect</code>, a destra, con un <code>ResizeObserver</code> (la percentuale di zoom cambia la larghezza) e un <code>MutationObserver</code> sulle classi (Excalidraw sostituisce parti del suo DOM al cambio di layout). La misura tiene conto dello zoom dell&#39;interfaccia dell&#39;app. Se l&#39;ancora non si trova il gruppo non si mostra; i comandi restano disponibili. Il gruppo non c&#39;è in modalità Zen e in presentazione.</li><li><strong>Dipendenza dichiarata dalle classi del fork.</strong> Il gruppo dipende da <code>.zoom-actions</code>, <code>.Island</code>, <code>.layer-ui__wrapper__footer-left</code> e, per il margine inferiore, <code>.App-bottom-bar</code>. Sono un dettaglio del fork, non un&#39;API: a ogni aggiornamento del fork (ADR-0028 chiede già di rieseguire gli e2e <code>drawing*</code>) <code>drawing-navigation.spec.ts</code> deve restare verde. Se le classi cambiano il danno è visibile e non silenzioso sui dati: i pulsanti spariscono, i comandi funzionano ancora, il margine inferiore torna quello che Excalidraw calcola da solo.</li><li><strong>Zoom sulla selezione</strong> (<code>drawing/viewport.ts</code>): <code>zoomTargets</code> sceglie gli elementi selezionati e vivi, oppure tutto il disegno se non c&#39;è selezione (o se la selezione non corrisponde a nessun elemento); <code>zoomToSelection</code> chiama <code>api.setViewport({ target, fit: &#39;contain&#39;, animation, offsets })</code>, con l&#39;animazione spenta se il sistema chiede di ridurre il movimento. L&#39;etichetta del pulsante cambia con la selezione («Zoom sulla selezione» / «Zoom su tutto il disegno»). Nessuna scorciatoia di default per il comando (<code>defaults: []</code>, assegnabile dalle impostazioni delle scorciatoie); il pulsante dichiara <code>aria-keyshortcuts=&quot;Shift+3&quot;</code>.</li><li><strong>Margine inferiore misurato da noi.</strong> <code>offsets: { ui: true }</code> fa misurare a Excalidraw il proprio ingombro, ma il layout «tray» non dichiara la barra inferiore. <code>bottomBarInset</code> la misura (<code>.App-bottom-bar</code> rispetto all&#39;area del canvas, in pixel del canvas) e <code>fitOffsets</code> aggiunge <code>bottom: inset + 24</code> (margine <code>FIT_PADDING</code>). Quando la barra non c&#39;è (layout completo, zen) il valore è <code>undefined</code> e non si aggiunge nulla.</li><li><strong>Il comando di zoom esce dalle azioni di scena.</strong> <code>drawing:zoom-to-fit-selected</code> non è più in <code>SCENE_ACTIONS</code> (<code>drawing/actions/registry.ts</code>) ma tra i comandi di <code>drawing/sceneCommands.ts</code> scritti a mano, con <code>feature: &#39;drawing.navigation&#39;</code>. È disponibile con un disegno aperto e il flag <code>drawings</code> acceso, anche in sola lettura (vault non modificabile, modalità vista) e <strong>senza</strong> il flag <code>drawing_actions</code>: cambia la vista, non il disegno. Il comando fratello <code>drawing:toggle-minimap</code> ha la stessa condizione. <code>SceneController</code> ha un metodo in più, <code>zoomToSelection()</code>.</li><li><strong>Mini-mappa con resa semplificata</strong> (<code>drawing/Minimap.tsx</code>, moduli puri <code>drawing/minimap/{geometry,model}.ts</code>): un canvas 2D di 220×150 px (<code>MINIMAP_SIZE</code>) in cui ogni elemento diventa una forma semplice (riquadro, ellisse, rombo, cornice, riquadro per immagini e testi, polilinea con al massimo 24 punti per linee e tratti liberi; ogni elemento lascia almeno un punto; i colori passano da <code>applyDarkModeFilter</code> nel tema scuro). Le forme si ricostruiscono al più ogni 200 ms (<code>REBUILD_MS</code>) e solo quando cambia la firma della scena; il riquadro della porzione visibile segue <code>onChange</code> e <code>onScrollChange</code>. Un clic o un trascinamento centrano la vista sul punto (<code>updateScene</code> con <code>CaptureUpdateAction.NEVER</code>: spostarsi non è un passo di annullamento); con il focus, le frecce spostano di un decimo della vista (metà con Maiusc) e Home inquadra tutto il disegno. Si nasconde in modalità Zen, in presentazione e mentre il menu degli stili di Excalidraw (<code>openMenu === &#39;shape&#39;</code>) si apre nello stesso angolo. Non è montata quando è spenta: spenta non costa nulla.</li><li><strong>Persistenza per dispositivo</strong> (<code>drawing/uiPrefs.ts</code>): la visibilità della mini-mappa sta in <code>localStorage</code>, chiave <code>clarae.drawing.minimap</code> (<code>1</code>/<code>0</code>), spenta finché l&#39;utente non la accende, e <strong>non</strong> in <code>.clarae/drawing.json</code>, che viaggia con la sincronizzazione: dipende dallo schermo e dal modo di lavorare su quel dispositivo. Nel workbench web è per browser. Se <code>localStorage</code> non è disponibile la scelta vale per la sessione.</li><li><strong>Registro e comandi.</strong> Nuova voce <code>drawing.navigation</code> in <code>shared/parity/features.yaml</code> con i comandi <code>drawing:zoom-to-fit-selected</code> e <code>drawing:toggle-minimap</code> (il primo si toglie da <code>drawing.scene-actions</code>); titoli i18n <code>commands.drawing_zoom_to_fit_selected</code> e <code>commands.drawing_toggle_minimap</code>, etichette in <code>drawing.footer.*</code> e <code>drawing.minimap.*</code>; icona <code>minimap</code> in <code>scripts/gen-icons.mjs</code>. Nessuna dipendenza nuova, nessun binding nuovo.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>&lt;Footer&gt;</code> di Excalidraw (soluzione del piano)</strong> — scartata: nel layout «tray» lo slot non è reso, quindi i pulsanti mancherebbero proprio sul disegno modificabile.</li><li><strong>Portal dentro il DOM del fork</strong> — scartata: scrivere dentro un albero che React di Excalidraw sostituisce a ogni cambio di layout dà elementi che spariscono o si duplicano, e lega il codice a dettagli interni molto più di una misura di sola lettura. Misurare l&#39;isola dello zoom e posizionare un elemento nostro accanto lega il codice alle stesse classi, ma senza scrivere nel DOM altrui.</li><li><strong><code>exportToCanvas</code> per la mini-mappa</strong> — scartata: è asincrona, ha un costo che cresce con la scena e con la risoluzione (font, immagini, formule) e andrebbe rifatta a ogni modifica; una vista d&#39;insieme di 220×150 px non ha bisogno di fedeltà. La resa semplificata ha costo lineare nel numero di elementi, è sincrona e si prova con funzioni pure.</li><li><strong>Visibilità della mini-mappa in <code>.clarae/drawing.json</code></strong> — scartata: il file si sincronizza e porterebbe la scelta di un dispositivo su un altro con uno schermo diverso.</li><li><strong>Una scorciatoia di default per i due comandi</strong> — scartata: le scorciatoie libere sono poche e Excalidraw ne ha di proprie; si assegnano dalle impostazioni delle scorciatoie.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Zoom sulla selezione e mini-mappa funzionano in modifica, in sola visualizzazione e su un vault in sola lettura, sul desktop e nel workbench web, con le stesse prove.</li><li>Si introduce una dipendenza dalle classi CSS del fork (punto 2): ogni aggiornamento di <code>@zsviczian/excalidraw</code> va accompagnato dall&#39;esecuzione di <code>drawing-navigation.spec.ts</code> sui due target. Il rischio è limitato (i pulsanti sparirebbero, nessun dato è toccato) e non si estende ad altro codice.</li><li>Il margine inferiore di un fit dipende da una misura nostra, non dal fork: se Excalidraw un giorno dichiarasse la barra del layout «tray» tra i suoi ingombri, <code>bottomInset</code> andrebbe tolto per non contarla due volte.</li><li>Non provato su una WebView reale (WKWebView, WebView2, WebKitGTK): gli e2e girano su Chromium con i binding simulati e sul core WASM. Il posizionamento del gruppo e la mini-mappa vanno verificati nella checklist manuale dei disegni (<a href="./../qa/m3-drawings-canvas.html"><code>docs/qa/m3-drawings-canvas.md</code></a>).</li><li>La mini-mappa non mostra i contenuti delle immagini (un riquadro) né il testo reale: è una carta d&#39;orientamento, non un&#39;anteprima.</li><li><strong>Recepito nello spec v1.6 (2026-11-15):</strong> §2.7.2, nuovo punto 10 «Navigazione»: <em>Zoom sulla selezione</em> (selezione, oppure tutto il disegno; anche in sola lettura), <em>Mini-mappa</em> (interruttore per dispositivo, nascosta in Zen e in presentazione; clic, trascinamento, frecce e Home); §2.2.1, nota alla riga «Excalidraw nativo»; Appendice C.4.</li></ul>',13)])])}const g=o(t,[["render",d]]);export{p as __pageData,g as default};
